 for(const s of[-1,1])for(let i=0;i<bays;i++){const xx=-w/2+(i+.5)*w/bays,wide=Math.min(2.9,w/bays*.59);if(Math.abs(xx)-wide/2<opening/2+.1)continue;b.n17Lattice(xx,3.0,s*faceZ,wide,2.35,s<0?PI:0);}
